package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.dto.ProgressSummary; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class StudyPlanningStrategyTest {private final List<ProgressSummary.TopicProgress> topics=List.of(new ProgressSummary.TopicProgress("SOLID",40,"WEAK",2),new ProgressSummary.TopicProgress("Patterns",90,"STRONG",2));@Test void balancedRespectsBudget(){var items=new BalancedStudyStrategy().build(LocalDate.of(2026,1,1),LocalDate.of(2026,1,3),60,topics);assertEquals(60,items.stream().mapToInt(StudyPlanningStrategy.Activity::minutes).sum());}@Test void weakStrategyPrioritizesWeakTopic(){var items=new WeakTopicFocusedStrategy().build(LocalDate.of(2026,1,1),LocalDate.of(2026,1,2),60,topics);assertTrue(items.getFirst().activity().contains("SOLID"));}@Test void examCramUsesWeakestFirst(){var items=new ExamCramStrategy().build(LocalDate.of(2026,1,1),LocalDate.of(2026,1,1),30,topics);assertTrue(items.getFirst().activity().contains("SOLID"));}}
